baseline.contents:
.hero {
  display: grid;
  gap: 1rem;
  padding: 4rem 2rem;
  font-family: system-ui, sans-serif;
}

.hero-title {
  margin: 0;
  font-size: 3.5rem;
  letter-spacing: -0.02em;
}

/* second place styling the same element in the same file — the multi-range
   case for the rule list */
.hero-title {
  font-weight: 800;
}

/* badge case: @media rules are surfaced, not evaluated */
@media (max-width: 640px) {
  .hero-title {
    font-size: 2rem;
  }
}

.hero-lead {
  margin: 0;
  font-size: 1.25rem;
  color: #475569;
}

.hero-cta {
  justify-self: start;
  padding: 0.5rem 1rem;
  border-radius: 0.5rem;
  background: #0f172a;
  color: #fff;
  text-decoration: none;
}

